#include <bits/stdc++.h>
using namespace std;

/*
We need the shortest lowercase string that is NOT a substring of any given dangerous password.
Among those with minimum length, choose lexicographically smallest.

Build a suffix automaton (SAM) for all dangerous passwords, but reset the "last" state for each
new password so substrings never cross password boundaries.

For any state, if it has fewer than 26 outgoing transitions, then there exists a missing next
character and thus a string ending here + that character is absent.

Let dp[v] = minimum length of a string that starts from state v and becomes absent.
Then:
  dp[v] = 1, if some character is missing from v
  otherwise dp[v] = 1 + min(dp[to]) over all 26 transitions

Answer is reconstructed from the initial state by always choosing the smallest character c such that:
- if transition by c is missing and dp[root] == 1, take it
- else if transition exists and dp[root] == 1 + dp[to], take it and continue

This works because every path in SAM corresponds to some substring of the input set.
*/

struct SuffixAutomaton {
    struct State {
        int link, len;
        int next[26];
        State() : link(-1), len(0) {
            memset(next, -1, sizeof(next));
        }
    };

    vector<State> st;
    int last, root;

    SuffixAutomaton() {
        st.reserve(1 << 20);
        st.push_back(State());
        root = last = 0;
    }

    void reset_last() {
        last = root;
    }

    void extend(char ch) {
        int c = ch - 'a';
        int cur = (int)st.size();
        st.push_back(State());
        st[cur].len = st[last].len + 1;

        int p = last;
        while (p != -1 && st[p].next[c] == -1) {
            st[p].next[c] = cur;
            p = st[p].link;
        }

        if (p == -1) {
            st[cur].link = root;
        } else {
            int q = st[p].next[c];
            if (st[p].len + 1 == st[q].len) {
                st[cur].link = q;
            } else {
                int clone = (int)st.size();
                st.push_back(st[q]);
                st[clone].len = st[p].len + 1;
                while (p != -1 && st[p].next[c] == q) {
                    st[p].next[c] = clone;
                    p = st[p].link;
                }
                st[q].link = st[cur].link = clone;
            }
        }
        last = cur;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    SuffixAutomaton sam;

    for (int i = 0; i < N; ++i) {
        string s;
        cin >> s;
        sam.reset_last();
        for (char c : s) sam.extend(c);
    }

    int SZ = (int)sam.st.size();
    vector<int> dp(SZ, -1);

    function<int(int)> solve = [&](int v) -> int {
        int &res = dp[v];
        if (res != -1) return res;

        res = INT_MAX;
        bool missing = false;
        for (int c = 0; c < 26; ++c) {
            if (sam.st[v].next[c] == -1) {
                missing = true;
                res = 1;
                break;
            }
        }
        if (missing) return res;

        for (int c = 0; c < 26; ++c) {
            int to = sam.st[v].next[c];
            res = min(res, 1 + solve(to));
        }
        return res;
    };

    solve(sam.root);

    string ans;
    int v = sam.root;
    while (true) {
        for (int c = 0; c < 26; ++c) {
            int to = sam.st[v].next[c];
            if (to == -1) {
                if (dp[v] == 1) {
                    ans.push_back(char('a' + c));
                    cout << ans << '\n';
                    return 0;
                }
            } else {
                if (dp[v] == 1 + dp[to]) {
                    ans.push_back(char('a' + c));
                    v = to;
                    break;
                }
            }
        }
    }

    return 0;
}

