#define MAXN 100
#define MAXLEN 100
#define MAX_SUB (MAXN * MAXLEN * (MAXLEN + 1) / 2 + 1000)

typedef struct {
    char **data;
    int size;
    int capacity;
} HashSet;

void hashset_init(HashSet *set) {
    set->size = 0;
    set->capacity = 16;
    set->data = calloc(set->capacity, sizeof(char*));
}

unsigned long hash(const char *str) {
    unsigned long h = 5381;
    int c;
    while ((c = *str++))
        h = ((h << 5) + h) + c;
    return h;
}

void hashset_insert(HashSet *set, const char *str) {
    if (set->size >= set->capacity * 0.75) {
        set->capacity *= 2;
        set->data = realloc(set->data, set->capacity * sizeof(char*));
    }
    unsigned long idx = hash(str) % set->capacity;
    set->data[set->size] = strdup(str);
    set->size++;
}

int hashset_contains(HashSet *set, const char *str) {
    for (int i = 0; i < set->size; i++) {
        if (strcmp(set->data[i], str) == 0)
            return 1;
    }
    return 0;
}

void hashset_free(HashSet *set) {
    for (int i = 0; i < set->size; i++)
        free(set->data[i]);
    free(set->data);
}

int main() {
    int N;
    char passwords[MAXN][MAXLEN+1];
    HashSet substrings;
    hashset_init(&substrings);

    scanf("%d", &N);
    for (int i = 0; i < N; i++) {
        scanf("%s", passwords[i]);
        int len = strlen(passwords[i]);
        for (int start = 0; start < len; start++) {
            char buf[MAXLEN+1] = {0};
            for (int end = start; end < len; end++) {
                buf[end - start] = passwords[i][end];
                buf[end - start + 1] = '\0';
                hashset_insert(&substrings, buf);
            }
        }
    }

    // BFS over strings in lexicographic order for each length
    char queue[200000][MAXLEN+1];
    int front = 0, rear = 0;
    for (char c = 'a'; c <= 'z'; c++) {
        char s[2] = {c, '\0'};
        if (!hashset_contains(&substrings, s)) {
            printf("%s\n", s);
            hashset_free(&substrings);
            return 0;
        }
        strcpy(queue[rear++], s);
    }

    while (front < rear) {
        char *cur = queue[front++];
        int len = strlen(cur);
        for (char c = 'a'; c <= 'z'; c++) {
            char next[MAXLEN+2];
            strcpy(next, cur);
            next[len] = c;
            next[len+1] = '\0';
            if (!hashset_contains(&substrings, next)) {
                printf("%s\n", next);
                hashset_free(&substrings);
                return 0;
            }
            strcpy(queue[rear++], next);
        }
    }

    hashset_free(&substrings);
    return 0;
}

