static int cmp_str(const void *a, const void *b) {
    const char * const *sa = (const char * const *)a;
    const char * const *sb = (const char * const *)b;
    return strcmp(*sa, *sb);
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char **arr = (char **)malloc((size_t)N * sizeof(char *));
    if (!arr) return 0;

    int total_len = 0;
    for (int i = 0; i < N; i++) {
        char buf[1000005];
        if (scanf("%s", buf) != 1) return 0;
        int len = (int)strlen(buf);
        total_len += len;
        arr[i] = (char *)malloc((size_t)len + 1);
        if (!arr[i]) return 0;
        memcpy(arr[i], buf, (size_t)len + 1);
    }

    qsort(arr, (size_t)N, sizeof(char *), cmp_str);

    int uniqueN = 0;
    for (int i = 0; i < N; i++) {
        if (uniqueN == 0 || strcmp(arr[i], arr[uniqueN - 1]) != 0) {
            arr[uniqueN++] = arr[i];
        } else {
            free(arr[i]);
        }
    }
    N = uniqueN;

    int max_states = 2 * total_len + 5;
    State *st = (State *)malloc((size_t)max_states * sizeof(State));
    if (!st) return 0;

    for (int c = 0; c < ALPHA; c++) st[0].next[c] = -1;
    st[0].link = -1;
    st[0].len = 0;
    int sz = 1, last = 0;

    for (int i = 0; i < N; i++) {
        const char *s = arr[i];
        int p;
        last = 0; /* reset for each string to represent union of substrings */
        for (int idx = 0; s[idx]; idx++) {
            int c = s[idx] - 'a';
            int cur = sz++;
            st[cur].len = st[last].len + 1;
            for (int k = 0; k < ALPHA; k++) st[cur].next[k] = -1;

            p = last;
            while (p != -1 && st[p].next[c] == -1) {
                st[p].next[c] = cur;
                p = st[p].link;
            }

            if (p == -1) {
                st[cur].link = 0;
            } else {
                int q = st[p].next[c];
                if (st[p].len + 1 == st[q].len) {
                    st[cur].link = q;
                } else {
                    int clone = sz++;
                    st[clone] = st[q];
                    st[clone].len = st[p].len + 1;
                    while (p != -1 && st[p].next[c] == q) {
                        st[p].next[c] = clone;
                        p = st[p].link;
                    }
                    st[q].link = st[cur].link = clone;
                }
            }
            last = cur;
        }
    }

    int *dist = (int *)malloc((size_t)sz * sizeof(int));
    int *q = (int *)malloc((size_t)sz * sizeof(int));
    int *parent = (int *)malloc((size_t)sz * sizeof(int));
    char *pch = (char *)malloc((size_t)sz * sizeof(char));
    if (!dist || !q || !parent || !pch) return 0;

    for (int i = 0; i < sz; i++) dist[i] = -1;

    int head = 0, tail = 0;
    dist[0] = 0;
    q[tail++] = 0;
    parent[0] = -1;
    pch[0] = 0;

    int end_state = -1;
    char end_char = 0;

    while (head < tail) {
        int v = q[head++];

        for (int c = 0; c < ALPHA; c++) {
            int to = st[v].next[c];
            if (to == -1) {
                end_state = v;
                end_char = (char)('a' + c);
                head = tail; /* break outer loop */
                break;
            }
            if (dist[to] == -1) {
                dist[to] = dist[v] + 1;
                parent[to] = v;
                pch[to] = (char)('a' + c);
                q[tail++] = to;
            }
        }
    }

    int len = dist[end_state] + 1;
    char *ans = (char *)malloc((size_t)len + 1);
    if (!ans) return 0;
    ans[len] = '\0';
    ans[len - 1] = end_char;

    int cur = end_state;
    for (int pos = len - 2; pos >= 0; pos--) {
        ans[pos] = pch[cur];
        cur = parent[cur];
    }

    printf("%s\n", ans);

    free(ans);
    free(dist);
    free(q);
    free(parent);
    free(pch);
    free(st);
    for (int i = 0; i < N; i++) free(arr[i]);
    free(arr);

    return 0;
}

