public class Main {
    static int[][] sa;
    static int[] link, len;
    static int last, sz;
    static final int ALPHA = 26;

    static void init(int maxN) {
        sa = new int[maxN][ALPHA];
        link = new int[maxN];
        len = new int[maxN];
        sz = 0; last = 0;
        Arrays.fill(sa[0], -1);
        len[0] = 0; link[0] = -1;
        sz = 1;
    }

    static void extend(int c) {
        // Check if transition already exists from last
        if (sa[last][c] != -1) {
            int q = sa[last][c];
            if (len[q] == len[last] + 1) { last = q; return; }
            int clone = sz++;
            len[clone] = len[last] + 1;
            link[clone] = link[q];
            sa[clone] = Arrays.copyOf(sa[q], ALPHA);
            link[q] = clone;
            int p = last;
            while (p != -1 && sa[p][c] == q) { sa[p][c] = clone; p = link[p]; }
            last = clone;
            return;
        }
        int cur = sz++;
        len[cur] = len[last] + 1;
        Arrays.fill(sa[cur], -1);
        int p = last;
        while (p != -1 && sa[p][c] == -1) { sa[p][c] = cur; p = link[p]; }
        if (p == -1) link[cur] = 0;
        else {
            int q = sa[p][c];
            if (len[q] == len[p] + 1) link[cur] = q;
            else {
                int clone = sz++;
                len[clone] = len[p] + 1;
                link[clone] = link[q];
                sa[clone] = Arrays.copyOf(sa[q], ALPHA);
                Arrays.fill(sa[cur] = sa[cur], -1); // reset cur
                sa[cur] = new int[ALPHA]; Arrays.fill(sa[cur], -1);
                link[q] = clone; link[cur] = clone;
                while (p != -1 && sa[p][c] == q) { sa[p][c] = clone; p = link[p]; }
            }
        }
        last = cur;
    }
    // BFS to find shortest, lex smallest string not in SAM
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int maxLen = 0;
        String[] passwords = new String[N];
        for (int i = 0; i < N; i++) { passwords[i] = sc.next(); maxLen += passwords[i].length(); }
        init(2 * maxLen + 10);
        for (String p : passwords) { last = 0; for (char c : p.toCharArray()) extend(c - 'a'); }
        // BFS
        Queue<int[]> queue = new LinkedList<>(); // state, parent_state, char
        queue.add(new int[]{0, -1, -1});
        Map<Integer,int[]> parent = new HashMap<>();
        parent.put(0, new int[]{-1,-1});
        // We need to track path
        // Use BFS with path reconstruction
        Queue<Object[]> bfs = new LinkedList<>();
        bfs.add(new Object[]{0, ""});
        Set<Integer> visited = new HashSet<>(); visited.add(0);
        while (!bfs.isEmpty()) {
            Object[] cur = bfs.poll();
            int state = (int)cur[0]; String path = (String)cur[1];
            for (int c = 0; c < 26; c++) {
                if (sa[state][c] == -1) { System.out.println(path + (char)('a'+c)); return; }
                int ns = sa[state][c];
                if (!visited.contains(ns)) { visited.add(ns); bfs.add(new Object[]{ns, path+(char)('a'+c)}); }
            }
        }
    }
}

