public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);

        String[] arr = new String[n];
        int maxLen = 0;
        long totalLen = 0;
        for (int i = 0; i < n; i++) {
            arr[i] = fs.next();
            if (arr[i] == null) arr[i] = "";
            maxLen = Math.max(maxLen, arr[i].length());
            totalLen += arr[i].length();
        }

        // Try lengths from 1 upward.
        // For a fixed length L:
        // - collect all distinct substrings of length L from dangerous passwords
        // - if fewer than 26^L exist, answer exists at this length
        // - generate lexicographically smallest missing one
        for (int L = 1; ; L++) {
            long totalPossible = 1;
            boolean overflow = false;
            for (int i = 0; i < L; i++) {
                if (totalPossible > Long.MAX_VALUE / 26) {
                    overflow = true;
                    break;
                }
                totalPossible *= 26;
            }

            HashSet<Long> seen = new HashSet<>();
            long pow = 1;
            for (int i = 1; i < L; i++) pow *= 26;

            for (String s : arr) {
                if (s.length() < L) continue;

                long code = 0;
                for (int i = 0; i < L; i++) {
                    code = code * 26 + (s.charAt(i) - 'a');
                }
                seen.add(code);

                for (int i = L; i < s.length(); i++) {
                    code = (code % pow) * 26 + (s.charAt(i) - 'a');
                    seen.add(code);
                }
            }

            if (overflow || seen.size() < totalPossible) {
                long ansCode = findMissingLexicographicallySmallest(seen, L);
                System.out.println(decode(ansCode, L));
                return;
            }

            // Safety: if L > maxLen, then no substrings of this length exist, so "a...a" is answer.
            // In practice loop returns earlier, but keep this for completeness.
            if (L > maxLen) {
                char[] res = new char[L];
                Arrays.fill(res, 'a');
                System.out.println(new String(res));
                return;
            }
        }
    }

    static long findMissingLexicographicallySmallest(HashSet<Long> seen, int L) {
        return dfs(0, 0L, L, seen);
    }

    static long dfs(int depth, long prefix, int L, HashSet<Long> seen) {
        if (depth == L) {
            return seen.contains(prefix) ? -1 : prefix;
        }

        int rem = L - depth - 1;
        long blockSize = 1;
        for (int i = 0; i < rem; i++) blockSize *= 26;

        for (int c = 0; c < 26; c++) {
            long start = prefix * 26 + c;
            long base = start * blockSize;

            boolean full = true;
            for (long x = 0; x < blockSize; x++) {
                if (!seen.contains(base + x)) {
                    full = false;
                    break;
                }
            }

            if (!full) {
                long res = dfs(depth + 1, start, L, seen);
                if (res != -1) return res;
            }
        }
        return -1;
    }

    static String decode(long code, int L) {
        char[] res = new char[L];
        for (int i = L - 1; i >= 0; i--) {
            res[i] = (char) ('a' + (code % 26));
            code /= 26;
        }
        return new String(res);
    }
}

import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    dangerous = input_data[1:]

    # Collect all substrings of dangerous passwords into a set
    substr_set = set()
    for pwd in dangerous:
        m = len(pwd)
        for i in range(m):
            for j in range(i+1, m+1):
                substr_set.add(pwd[i:j])

    # BFS over strings in lexicographic order
    q = deque()
    # Start with single letters
    for c in "abcdefghijklmnopqrstuvwxyz":
        if c not in substr_set:
            print(c)
            return
        q.append(c)

    while q:
        s = q.popleft()
        # Extend with each letter
        for c in "abcdefghijklmnopqrstuvwxyz":
            cand = s + c
            if cand not in substr_set:
                print(cand)
                return
            q.append(cand)

if __name__ == "__main__":
    solve()
